-- =============================================================================
-- Auto Business — Tajik-Neelakanthi Dasha-Phal rules (migration 024)
-- 87 rules of the Varshatantra Dasha-phala-adhyaya (shlokas 1-62, pp. 225-243):
-- Patyayini dasha-krama vidhi, the four strength-level phal per planet-dasha
-- (+ upचय upgrade), Lagna dasha, antardasha vidhi and 37 bhavastha-graha rules.
-- Additive "दशा-फल" option in the Varshaphal prediction dropdown.
-- Source: docs/tajik_neelakanthi_dasha_phal_niyam.md.
-- =============================================================================
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS dasha_phal (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    rule_id VARCHAR(16) NOT NULL,
    section VARCHAR(48) NOT NULL,
    shloka VARCHAR(24) NOT NULL,
    category VARCHAR(12) NOT NULL,          -- shubh/ashubh/mrityu/mishrit/niyam
    cond_text TEXT NOT NULL,
    phal_text TEXT NOT NULL,
    note_text TEXT NULL,
    language VARCHAR(8) NOT NULL DEFAULT 'hi',
    updated_by_staff_id BIGINT UNSIGNED NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id), UNIQUE KEY uq_dp (rule_id, language)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE section=VALUES(section), shloka=VALUES(shloka), category=VALUES(category),
    cond_text=VALUES(cond_text), phal_text=VALUES(phal_text), note_text=VALUES(note_text);

-- Bala-tier thresholds (Panchavargeeya bala, of 20) — configurable (impl note 2).
ON DUPLICATE KEY UPDATE cfg_value=VALUES(cfg_value);
