INSERT INTO dasha_phal (rule_id,section,shloka,category,cond_text,phal_text,note_text,language) VALUES
('VIDHI_01','दशाक्रम-विधि','१','niyam','वर्षप्रवेश के स्पष्ट लग्न तथा सातों ग्रहों के राशि छोड़कर केवल अंशादि (भुक्तांश) लें।','जिसके अंश सबसे अधिक हों उससे घटते क्रम में वर्ष का दशाक्रम बनता है।','पात्यायिनी दशा — संज्ञातन्त्र में विस्तृत।','hi'),
('VIDHI_02','दशाक्रम-विधि','२','niyam','अधिक अंश वाले में से क्रमशः न्यून अंश घटाएँ — शेष = उस ग्रह/लग्न का "शुद्धांश"; सबसे न्यून का शुद्धांश वही रहता है। सर्वाधिक अंश (परम-शुद्धांश-योग) से वर्ष-मान का अनुपात लें।','शुद्धांश × (वर्ष-मान ÷ कुल अंश) = उस दशा का मान।','','hi'),
('VIDHI_03','दशाक्रम-विधि','३','niyam','शुद्धांश को ध्रुवांक से गुणा कर दिन-घटी आदि में दशा-मान लाएँ।','उस दशा में उस ग्रह का शास्त्रोक्त फल कहें।','','hi'),
('VIDHI_04','दशाक्रम-विधि','४','niyam','दो ग्रहों के शुद्धांश समान हों तो बली की दशा पहले; बल भी समान हो तो पूर्व (पहले गिना गया) की; लग्न से साम्य हो तो लग्नपति के बल से विचार करें।','दशाक्रम-निर्णय (tie-breaking)।','','hi'),
('LAGNA_D_01','लग्न-दशा','५','shubh','लग्न की उत्तम (शोभना) दशा हो — लग्नेश पूर्णबली।','सुवर्ण, मोती, धन, आरोग्य और स्वामी से समीचीन सम्मान।','','hi'),
('LAGNA_D_02','लग्न-दशा','६','mishrit','लग्न की मध्यम-बल दशा हो।','भाग्य से धन-लाभ; मान-हीन मनुष्य की सेवा; मन में विकार।','','hi'),
('LAGNA_D_03','लग्न-दशा','७','ashubh','लग्न की अधम (कष्टा) दशा हो — लग्नेश हीन/नष्टबली।','विदेश-यात्रा, कष्ट, बुद्धि-नाश, निष्प्रयोजन धन की बर्बादी (अपव्यय) और मान-हानि।','','hi'),
('LAGNA_D_04','लग्न-दशा','८','ashubh','क्रूर (क्रूर-राशि) लग्न की मध्य-बल दशा हो।','थोड़ा सुख, धन का खर्च, शरीर में पीड़ा और दुर्बलता, मृत्यु तथा लड़ाई (विरोध) उत्पन्न करने वाली।','','hi'),
('LAGNA_D_05','लग्न-दशा','४४','shubh','लग्न-दशा का फल = लग्न-स्वामी के बल के तुल्य (पूर्ण→पूर्ण शुभ, मध्य→मध्यम, हीन→बहुत थोड़ा)। विशेष: चर लग्न — प्रथम द्रेष्काण।','लग्न-दशा शुभ फल देती है।','चर लग्न: द्वितीय द्रेष्काण → मध्यम; तृतीय → अधम। द्विस्वभाव लग्न: प्रथम → अधम, द्वितीय → मध्यम, तृतीय → शुभ।','hi'),
('LAGNA_D_06','लग्न-दशा','४५','niyam','स्थिर लग्न — प्रथम द्रेष्काण → अनिष्ट; द्वितीय → शुभ; तृतीय → सम फल।','द्रेष्काण-भेद से लग्न-दशा-फल (पूर्वाचार्य-मत)।','लग्न शुभग्रहों व अपने स्वामी से युक्त/दृष्ट हो तो अशुभ फल भी शुभ और शुभ फल शुभतर; लग्न-स्वामी पापग्रहों से दृष्ट/युक्त हो तो कष्टकारक फल।','hi'),
('SURYA_D_01','सूर्य-दशा','९','shubh','सूर्य-दशा — दशापति पूर्णबली हो।','हाथी, घोड़ा, सुवर्ण, कपड़े, रत्न; राजा से सम्मान, प्रतिष्ठा; देवता व ब्राह्मणों के पूजन आदि से यश।','','hi'),
('SURYA_D_02','सूर्य-दशा','१०','mishrit','सूर्य-दशा — दशापति मध्यबली हो।','पूर्वोक्त फल मध्यम मात्रा में; ग्राम का अधिकार, उद्योग (व्यवसाय) व धैर्य से तथा कुल के अनुमान से सुखादि की प्राप्ति।','','hi'),
('SURYA_D_03','सूर्य-दशा','११','ashubh','सूर्य-दशा — दशापति बहुत थोड़ा/अल्प/हीनबली हो।','अपने जनों से लड़ाई का दुःख, मतिभ्रम, पित्त-रोग, अपने तेज का विनाश और शत्रु से दबाव (घर्षण)।','','hi'),
('SURYA_D_04','सूर्य-दशा','१२','ashubh','सूर्य-दशा — दशापति नष्टबली हो।','राजा और शत्रु से भय, धन की बर्बादी; स्त्री, पुत्र, मित्र आदि से विवाद; बुद्धिभ्रम और रोग।','','hi'),
('SURYA_D_05','सूर्य-दशा','१३','niyam','सूर्य छठे, तीसरे, दसवें या ग्यारहवें (उपचय) स्थान में बैठा हो।','नष्टबल → आधा शुभ; हीनबल → मध्यम; मध्यबल → शुभ; पूर्णबल → अत्यन्त शुभ फल।','स्थान-जन्य फल-उन्नयन (upgrade) नियम।','hi'),
('CHANDRA_D_01','चन्द्र-दशा','१४','shubh','चन्द्र-दशा — दशापति पूर्णबली हो।','सफेद कपड़े, माला, मोती, स्त्री-संगम, राज्य, सुख, भूमि-लाभ, यश, कान्ति और बल की वृद्धि।','','hi'),
('CHANDRA_D_02','चन्द्र-दशा','१५','mishrit','चन्द्र-दशा — दशापति मध्यबली हो।','पूर्वोक्त सब फल मध्यम; वाणिज्य, मित्र, कपड़े, गृह, सुख, धर्म-वृद्धि और खेती से अनाज का लाभ।','','hi'),
('CHANDRA_D_03','चन्द्र-दशा','१६','ashubh','चन्द्र-दशा — दशापति बहुत थोड़ा/अल्प/हीनबली हो।','कफ-रोग, कान्ति-नाश, मित्रादि से वैर, कन्या-जन्म, धर्म व धन का नाश और थोड़ा सुख।','','hi'),
('CHANDRA_D_04','चन्द्र-दशा','१७','ashubh','चन्द्र-दशा — दशापति नष्टबली हो।','बदनामी से भय, धन व धर्म का नाश, शीत-रोग, स्त्री-पुत्र-मित्र से वैर, चित्त की चंचलता, स्वादहीन अनाज का भोजन।','','hi'),
('CHANDRA_D_05','चन्द्र-दशा','१८','niyam','चन्द्रमा ६, ८, १२ से इतर राशियों (भावों) में बैठा हो।','नष्टबल → आधा शुभ; हीनबल → मध्यम; मध्यबल → शुभ; पूर्णबल → अत्यन्त शुभ फल।','स्थान-जन्य फल-उन्नयन (upgrade) नियम।','hi'),
('MANGAL_D_01','मङ्गल-दशा','१९','shubh','मङ्गल-दशा — दशापति पूर्णबली हो।','सेनापतित्व, संग्राम में जय; मूँगा, सोना, लाल कपड़े आदि का लाभ; प्रिय साहस-कर्म।','','hi'),
('MANGAL_D_02','मङ्गल-दशा','२०','mishrit','मङ्गल-दशा — दशापति मध्यबली हो।','कुल के अनुमान से धन; राजा से अधिकार-लाभ और उस अधिकार में प्रधानता; तेज, कान्ति व बल-वृद्धि।','','hi'),
('MANGAL_D_03','मङ्गल-दशा','२१','ashubh','मङ्गल-दशा — दशापति बहुत थोड़ा/अल्प/हीनबली हो।','शरीर में पित्त-ताप से रोग, शत्रु से भय, बन्धन, मुख से खून गिरना और निरन्तर अपने भाई-बन्धुओं से भय/वैर।','','hi'),
('MANGAL_D_04','मङ्गल-दशा','२२','ashubh','मङ्गल-दशा — दशापति नष्टबली हो।','उग्र विवाद अथवा संग्राम, चोरों का भय, रक्त-विकार, ज्वर, विपत्ति, विजातीय जन से धन-हरण और खाज-दाद (खर्जू) रोग।','','hi'),
('MANGAL_D_05','मङ्गल-दशा','२३','niyam','मङ्गल तीसरे, छठे या ग्यारहवें स्थान में स्थित हो।','नष्टबल → आधा शुभ; हीनबल → मध्यम; मध्यबल → शुभ; पूर्णबल → अत्यन्त शुभ फल।','स्थान-जन्य फल-उन्नयन (upgrade) नियम।','hi'),
('BUDH_D_01','बुध-दशा','२४','shubh','बुध-दशा — दशापति पूर्णबली हो।','गणित व सुन्दर कारीगरी (शिल्प) के यश की वृद्धि; राजादिकों की सफल सेवा; राजदूत बनना; निन्दा-रहित गुणों का उदय।','','hi'),
('BUDH_D_02','बुध-दशा','२५','mishrit','बुध-दशा — दशापति मध्यबली हो।','गुरुजनों, मित्रों, लेख, काव्य और कारीगरों से धन की प्राप्ति; लड़कों, मित्रों व बन्धुओं के समागम से मध्यम सुख।','','hi'),
('BUDH_D_03','बुध-दशा','२६','ashubh','बुध-दशा — दशापति बहुत थोड़ा/अल्प/हीनबली हो।','मान का नाश, अपने जनों से झगड़ा (स्वजन-अपवाद), अकारण कोप से अनिष्ट, धन का खर्च और रोग-भय।','','hi'),
('BUDH_D_04','बुध-दशा','२७','ashubh','बुध-दशा — दशापति नष्टबली हो।','अपनी बुद्धि के दोष से वध/बन्धन-भय, दूर-गमन, वात व कफ रोग से पीड़ा; अपना गाड़ा हुआ (निखात) धन न मिलना।','','hi'),
('BUDH_D_05','बुध-दशा','२८','niyam','बुध छठे, आठवें, बारहवें से इतर किसी स्थान में स्थित हो।','नष्टबल → आधा शुभ; हीनबल → मध्यम; मध्यबल → शुभ; पूर्णबल → अत्यन्त शुभ फल।','स्थान-जन्य फल-उन्नयन (upgrade) नियम।','hi'),
('GURU_D_01','गुरु-दशा','२९','shubh','गुरु-दशा — दशापति पूर्णबली हो।','राजा, मित्र तथा गुरुजनों से सम्मान; प्रसिद्धि, धन, सुख का लाभ; बल का अतिरेक और सिद्धि (बिना प्रयास वांछित कार्यों की सिद्धि)।','','hi'),
('GURU_D_02','गुरु-दशा','३०','mishrit','गुरु-दशा — दशापति मध्यबली हो।','धर्म में मति, मन्त्रि-जनों से मित्रता, मान-धन-सुख का लाभ, बल का अतिरेक और कार्य-सिद्धि।','','hi'),
('GURU_D_03','गुरु-दशा','३१','ashubh','गुरु-दशा — दशापति बहुत थोड़ा/अल्प/हीनबली हो।','रोग, गरीबी, शत्रु से भय, कान का रोग, धर्म और धन का नाश तथा वैराग्य; अर्थ तथा गुणों की अप्राप्ति।','','hi'),
('GURU_D_04','गुरु-दशा','३२','ashubh','गुरु-दशा — दशापति नष्टबली हो।','दुःख तथा कफ-रोग; स्त्री, पुत्र, अपने जनों और शत्रुजनों से भय; धर्म व धन का नाश तथा शरीर में पीड़ा।','','hi'),
('GURU_D_05','गुरु-दशा','३३','niyam','बृहस्पति छठे, आठवें, बारहवें से इतर स्थान में हो।','नष्टबल → आधा शुभ; हीनबल → मध्यम; मध्यबल → शुभ; पूर्णबल → अत्यन्त शुभ फल।','स्थान-जन्य फल-उन्नयन (upgrade) नियम।','hi'),
('SHUKRA_D_01','शुक्र-दशा','३४','shubh','शुक्र-दशा — दशापति पूर्णबली हो।','सुख, माला, सुगन्धित द्रव्य, सुवर्ण, कपड़े, स्त्री-सुख, घोड़े आदि का लाभ, पुत्र-प्राप्ति, प्रसिद्धि, प्रसन्नता, आरोग्य, गान में प्रीति और पद की प्राप्ति।','','hi'),
('SHUKRA_D_02','शुक्र-दशा','३५','mishrit','शुक्र-दशा — दशापति मध्यबली हो।','व्यापार से धन तथा खेती से धन का लाभ; मीठे अनाज का भोजन, कपड़े व भोगों का लाभ; मित्र और स्त्री-पुत्रों से सुख।','','hi'),
('SHUKRA_D_03','शुक्र-दशा','३६','ashubh','शुक्र-दशा — दशापति बहुत थोड़ा/अल्प/हीनबली हो।','मतिभ्रम; ज्ञान, यश, धन का नाश; कुत्सित अनाज का भोजन, दुःख, रोग से पीड़ा; ससुराल-वालों (स्त्री-पक्ष) से वैर तथा शत्रुओं से झगड़ा।','','hi'),
('SHUKRA_D_04','शुक्र-दशा','३७','ashubh','शुक्र-दशा — दशापति नष्टबली हो।','विदेश-यात्रा, स्वजनों से विरोध; पुत्र, धन और भार्या — इनसे विपत्ति; रोग, मतिभ्रम तथा महान् दुःख (व्यसन)।','','hi'),
('SHUKRA_D_05','शुक्र-दशा','३८','niyam','शुक्र छठे, आठवें, बारहवें से इतर स्थान में स्थित हो।','नष्टबल → आधा शुभ; हीनबल → मध्यम; मध्यबल → शुभ; पूर्णबल → अत्यन्त शुभ फल।','स्थान-जन्य फल-उन्नयन (upgrade) नियम।','hi'),
('SHANI_D_01','शनि-दशा','३९','shubh','शनि-दशा — दशापति पूर्णबली हो।','नवीन घर, कपड़े, भूमि और सुख की प्राप्ति; बाग, कुआँ, तालाब का निर्माण; म्लेच्छों के अति-संसर्ग से राज-द्वार पहुँचकर राजा से धन।','','hi'),
('SHANI_D_02','शनि-दशा','४०','mishrit','शनि-दशा — दशापति मध्यबली हो।','गधा, ऊँट, उड़द, अण्डज-पक्षियों के व्यवसाय से धन; वृद्धा स्त्री के साथ भोग; किला (दुर्ग)-रक्षा के अधिकार की चिन्ता; रस-रहित अन्नों का भोजन।','','hi'),
('SHANI_D_03','शनि-दशा','४१','ashubh','शनि-दशा — दशापति बहुत थोड़ा/अल्प/हीनबली हो।','शत्रु व चोरों से दुःख; अपने जनों से अपवाद, गरीबी, रोग और शीघ्र उग्र वात-कोप।','','hi'),
('SHANI_D_04','शनि-दशा','४२','ashubh','शनि-दशा — दशापति नष्टबली हो।','धातु-सम्बन्धी (त्रिदोष-जनित) अनेक दुःख; स्त्री, पुत्र, मित्र तथा अपने जनों से विरोध; रोगों की वृद्धि; मरण-समान कष्ट।','','hi'),
('SHANI_D_05','शनि-दशा','४३','niyam','शनि तीसरे, छठे या ग्यारहवें स्थान में स्थित हो।','नष्टबल → आधा शुभ; हीनबल → मध्यम; मध्यबल → शुभ; पूर्णबल → अत्यन्त शुभ फल।','स्थान-जन्य फल-उन्नयन (upgrade) नियम।','hi'),
('ANTAR_01','अन्तर्दशा-विधि','४६','niyam','दशा-मान के समान ही (पात्यायिनी) विधि से, प्राक्-उक्त अंशों के अनुपात से अन्तर्दशाएँ (सावनीय दिनादि में) साधें।','अन्तर्दशा-गणना।','','hi'),
('ANTAR_02','अन्तर्दशा-विधि','४७','niyam','प्रत्येक दशा में पहली अन्तर्दशा स्वयं दशापति (पाकपति) की; तत्पश्चात् शेष ग्रहों की दशा-क्रम से।','अन्तर्दशा-क्रम।','फल शुभ-ईक्षण (शुभग्रह-दृष्टि) और मैत्री से विचार कर कहें।','hi'),
('ANTAR_03','अन्तर्दशा-विधि','४६–४९','niyam','अन्तर्दशा का फल भी (दशा की तरह) चार प्रकार का बल देखकर कहें; अन्तर्दशापति शुभग्रहों से दृष्ट/युक्त या शुभग्रह से मैत्री-युक्त हो।','उसी के अनुसार शुभ फल का विचार।','','hi'),
('ANTAR_04','अन्तर्दशा-विधि','४८–४९','niyam','वामनाचार्य-मत: शुभ अन्तर्दशाएँ — सूर्य-दशा में चन्द्र, मङ्गल, गुरु; चन्द्र में बुध, गुरु, शुक्र; मङ्गल में सूर्य, चन्द्र; बुध में गुरु, शुक्र; गुरु में सूर्य, चन्द्र, मङ्गल; शुक्र में बुध, गुरु, शनि; शनि में गुरु, बुध, शुक्र।','ये अन्तर्दशाएँ शुभ फल देती हैं; शेष सब अशुभ समझें।','देखें शीट "अन्तर्दशा_सारिणी"।','hi'),
('BHAV_01','भावस्थ-ग्रह-फल','५०','ashubh','सूर्य, मङ्गल, शनि — इनमें से कोई ग्रह (दशा में) लग्न में स्थित हो।','ज्वर, पीड़ा और धन-हानि।','तर्क: सूर्य लग्नस्थ → पित्त-ज्वर; पाप-युक्त चन्द्र → कफ-ज्वर; मङ्गल → शीतला-ज्वर; तीनों → त्रिदोष-ज्वर (कुन्तला)।','hi'),
('BHAV_02','भावस्थ-ग्रह-फल','५०','ashubh','अशुभ ग्रह-सहित चन्द्रमा लग्न में बैठा हो।','ज्वर से पीड़ा और धन की हानि।','','hi'),
('BHAV_03','भावस्थ-ग्रह-फल','५०','shubh','शुभग्रहों से युक्त पुष्ट-शरीर (पूर्ण) चन्द्रमा लग्न में स्थित हो।','सुख देता है।','','hi'),
('BHAV_04','भावस्थ-ग्रह-फल','५०','shubh','बुध तथा शुक्र (और गुरु) लग्न में हों।','धन-धान्य का लाभ।','','hi'),
('BHAV_05','भावस्थ-ग्रह-फल','५१','shubh','चन्द्र, बुध, गुरु, शुक्र — ये धन-स्थान (२) में बैठे हों।','धन-आगम और राज्य का सुख।','','hi'),
('BHAV_06','भावस्थ-ग्रह-फल','५१','ashubh','अशुभ ग्रह धन-स्थान में बैठा हो।','धन-हानि।','','hi'),
('BHAV_07','भावस्थ-ग्रह-फल','५१','ashubh','शनैश्चर धन-स्थान में हो।','राजा का भय; कार्य को नष्ट करता है।','','hi'),
('BHAV_08','भावस्थ-ग्रह-फल','५२','shubh','तृतीय भाव में अशुभ ग्रह बैठे हों।','धन, धर्म तथा राज्य का लाभ।','बली अशुभ ग्रह भ्रातृ-भाव में हों तो पृथ्वी (भूमि)-लाभ।','hi'),
('BHAV_09','भावस्थ-ग्रह-फल','५२','shubh','सहज (३) स्थान में शुभग्रह हों।','सुख, धन, पुत्र, मान, यश और विलास।','','hi'),
('BHAV_10','भावस्थ-ग्रह-फल','५२','shubh','तृतीय भाव में चन्द्रमा बैठा हो।','अत्यन्त आनन्द।','','hi'),
('BHAV_11','भावस्थ-ग्रह-फल','५३','ashubh','चौथे भाव में अशुभ ग्रह-युक्त चन्द्रमा स्थित हो।','कष्ट (व्यसन) और रोग।','','hi'),
('BHAV_12','भावस्थ-ग्रह-फल','५३','shubh','शुभग्रहों से युक्त पूर्ण चन्द्रमा सुख-भाव (४) में स्थित हो।','सुख देता है।','','hi'),
('BHAV_13','भावस्थ-ग्रह-फल','५३','shubh','शुभग्रह चौथे घर में हों।','विविध सुख।','','hi'),
('BHAV_14','भावस्थ-ग्रह-फल','५३','ashubh','चौथे घर में अशुभ ग्रह विराजमान हों।','सुख और धन का नाश, रोग, कष्ट (कष्ट) और अतुल भय।','','hi'),
('BHAV_15','भावस्थ-ग्रह-फल','५४','shubh','शुभग्रह (बुध, गुरु, शुक्र, पूर्णबल चन्द्र) पञ्चम भाव में हों।','पुत्र, धन और सुख का संचय।','','hi'),
('BHAV_16','भावस्थ-ग्रह-फल','५४','shubh','पञ्चम भाव में शुक्र स्थित हो।','अतिशय आनन्द (अति-हर्ष)।','','hi'),
('BHAV_17','भावस्थ-ग्रह-फल','५४','ashubh','अशुभ ग्रह (सूर्य, मङ्गल, शनि, क्षीण चन्द्र) पञ्चम स्थान में हों।','पुत्र, धन, सुख तथा बुद्धि हरने वाले; चोरी का डर, रोग और झगड़ा।','','hi'),
('BHAV_18','भावस्थ-ग्रह-फल','५५','shubh','छठे घर में अशुभ ग्रह हों।','द्रव्य-लाभ और सुख की प्राप्ति।','','hi'),
('BHAV_19','भावस्थ-ग्रह-फल','५५','shubh','मङ्गल छठे भाव में हो।','अत्यन्त हर्ष; शत्रुओं का नाश।','','hi'),
('BHAV_20','भावस्थ-ग्रह-फल','५५','ashubh','षष्ठ भाव में शुभग्रह स्थित हों।','भय, धन की बर्बादी और झगड़ा।','','hi'),
('BHAV_21','भावस्थ-ग्रह-फल','५५','ashubh','अशुभ ग्रह के साथ (क्षीण) चन्द्रमा छठे में हो।','रोग (कफ-ज्वर आदि) करता है।','','hi'),
('BHAV_22','भावस्थ-ग्रह-फल','५६','ashubh','अशुभ ग्रह-सहित चन्द्रमा सप्तम भाव में बैठा हो।','बीमारी तथा भय।','','hi'),
('BHAV_23','भावस्थ-ग्रह-फल','५६','ashubh','सातवें घर में अशुभ ग्रह हों।','स्त्री का नाश, झगड़ा और सेवक से भय।','','hi'),
('BHAV_24','भावस्थ-ग्रह-फल','५६','shubh','शुभग्रह सातवें स्थान में विद्यमान हों।','धन-लाभ, सुख की प्राप्ति, यश, राजा से मान का उदय और बन्धुजनों से सुख।','','hi'),
('BHAV_25','भावस्थ-ग्रह-फल','५७','ashubh','वर्षेश के समय अशुभ ग्रह-युक्त चन्द्रमा आठवें स्थान में बैठा हो।','मरण करता है।','केवल अशुभ ग्रह आठवें हों तो मरण-तुल्य फल।','hi'),
('BHAV_26','भावस्थ-ग्रह-फल','५७','ashubh','शुभग्रह आठवें स्थान में विराजमान हों।','अपने धातु (कारकत्व) के अनुसार रोग, धन-हानि और मान-क्षय।','अष्टम-स्थित शुभग्रहों के साथ इत्थशाल (मुथशिल) योग हो तो अनिष्ट फल भी शुभ हो जाता है।','hi'),
('BHAV_27','भावस्थ-ग्रह-फल','५८','ashubh','नवम स्थान में अशुभ ग्रह हों।','भाइयों से भय तथा पशुओं (गो-महिषी आदि) को पीड़ा।','कोई-कोई आचार्य: अशुभ ग्रह भी नवम भाव में शुभ-फलदायक हो जाते हैं।','hi'),
('BHAV_28','भावस्थ-ग्रह-फल','५८','shubh','नवम भाव में सूर्य हो।','अतिशय आनन्द (अति-मुद)।','','hi'),
('BHAV_29','भावस्थ-ग्रह-फल','५८','shubh','नवम स्थान में शुभग्रह हों।','धन और धर्म की वृद्धि।','','hi'),
('BHAV_30','भावस्थ-ग्रह-फल','५९','ashubh','दशम भाव में शनि स्थित हो।','पशु और धन का नाश।','','hi'),
('BHAV_31','भावस्थ-ग्रह-फल','५९','shubh','सूर्य-मङ्गल दोनों दशम घर में स्थित हों।','व्यापार और पराक्रम द्वारा धन और सुख।','','hi'),
('BHAV_32','भावस्थ-ग्रह-फल','५९','shubh','इनसे अन्य ग्रह (शुभग्रह) राज्य-भाव (१०) में हों।','धन, पुत्र और राजा के संग से सुख।','','hi'),
('BHAV_33','भावस्थ-ग्रह-फल','६०','shubh','सब शुभ या अशुभ ग्रह बली होकर ग्यारहवें भाव में हों।','धन-समूह, सुख तथा यश की बढ़ती; अच्छे मित्रों का साथ, बल और पुष्टि।','','hi'),
('BHAV_34','भावस्थ-ग्रह-फल','६०','ashubh','अशुभ ग्रह बल-रहित होकर ग्यारहवें स्थान में हों।','पुत्र, धन और बुद्धि — इनका नाश।','बल-रहित शुभग्रह आय-भाव में हों तो अल्प फल देते हैं।','hi'),
('BHAV_35','भावस्थ-ग्रह-फल','६१','ashubh','अशुभ ग्रह बारहवें स्थान में हों।','आँख-रोग, विवाद; राजा और चोर आदिकों से धन-हानि।','','hi'),
('BHAV_36','भावस्थ-ग्रह-फल','६१','mishrit','शुभग्रह बारहवें भाव में हों।','अच्छे (सत्) मार्ग में खर्च कराते हैं।','','hi'),
('BHAV_37','भावस्थ-ग्रह-फल','६१','shubh','शनैश्चर व्यय-भाव (१२) में हो।','हर्ष तथा वृद्धि देता है।','शनि का यह फल अन्य ग्रन्थों से विरुद्ध होने पर भी यहाँ (नीलकण्ठ-मत से) यही है।','hi'),
('ANT_01','उपसंहार','६२','niyam','ग्रन्थकार-वंश: गर्गाचार्य-वंश में ज्योतिष-शास्त्र-ज्ञाता चिन्तामणि पण्डित; उनके पुत्र अनन्त (जन्म-पद्धति के रचयिता); उनके पुत्र नीलकण्ठ — शिव(दैवज्ञ) की आज्ञा से भावस्थ ग्रहों की दशा के शुभाशुभ फल कहे।','उपसंहार-श्लोक (कोई फलादेश-नियम नहीं)।','','hi')
